// Custon chromatic hardware bloom.

void mainImage(out vec4 fragColor, in vec2 fragCoord){

    // Screen coordinates.
    vec2 uv = fragCoord/iResolution.xy;

    #if 0
    // Just the texture with no after effects.
    vec3 col = texture(iChannel0, uv).xyz;
    #else

    // Chromatic color grab.
    vec2 pix = vec2(-4./iResolution.x, 0);//*dot(uv - .5, uv - .5)
    float R = texture(iChannel0, uv - pix, pix.x).x;
    float G = texture(iChannel0, uv).y;
    float B = texture(iChannel0, uv + pix, pix.x).z;
    vec3 col = vec3(R, G, B);

    // Custom chromatic hardware bloom algorithm. Made up on
    // the spot.
    float a = 1., w = sqrt(.5);
    for (int i = 0; i<6; i++){

        // A bit of jitter.
        vec2 uv2 = uv + (texture(iChannel1, 
                         uv + fract(iTime*.071)).xy - .5)/iResolution.xy*2.;

        #if 1
        // Chromatic color grab for this level.
        R = texture(iChannel0, uv2 - pix, pix.x + float(i)).x;
        G = texture(iChannel0, uv2, float(i)).y;
        B = texture(iChannel0, uv2 + pix, pix.x + float(i)).z;
        vec3 colI = vec3(R, G, B);
        col += colI*w;
        #else
        // Just a regular color grab. Cheaper, but not chromatic.
        col += texture(iChannel0, uv2, float(i)).xyz*w;
        #endif

        a += w; // Weighted sum.
        w *= sqrt(.5); // Dropping the weight each level.
    }
    col /= a; // Average color.

    #endif

    // Cheap vignette.
    col *= max(1.1 - dot(uv - .5, uv - .5)*2., 0.);

    // Rough gamma correction.
    fragColor = vec4(pow(col, vec3(1./2.2)), 1);

}

// Rave @ The Cave visualizer based on the amazing job of 
// "Octahedral Traversal" by Shane
//
// Source: https://shadertoy.com/view/Nds3zl

/*

    Octahedral Traversal
    --------------------

    Traversing an octahedral field. Thanks to an article written by Fizzer 
    some time ago, this was an unexpectedly easy polyhedral traversal to code. 
    Without the article, it probably would have taken me ages. :) Technically, 
    this is a raymarched traversal, which requires a little more work, but 
    it's similar in concept to a standard traversal.

    Things like equal-sized rectangles pack together in an obvious fashion,
    which is right on top of one another. Some polyhedrons, like tetrahedrons
    and rhombic dodecahedrons are less obvious, but they all stack using the
    same orientation. The octahedrons, here, stack using 3 different 
    orientations, and those have to be considered when traversing.

    It sounds tricky, but it's not a big deal. I know of at least two ways to
    traverse these objects, but I did it in a similar fashion to the way in
    which Fizzer's article taught me, which is to divide space up into cubes,
    then snap the octahedrons to each face of the cube, take orientation into
    account, and render... Obviously, I've skipped some details, but they're
    all there in the code. By the way, if you do want to make one of these,
    looking at Fizzer's example might make more sense.

    Performing a raymarched traversal requires more work -- and GPU power --
    but allows for a few niceties like soft shadows, simple AO, and CSG, which
    means you can create more interesting scenes. However, I kept things pretty
    simple.

    I'd say the most interesting thing about this example is the weird looking
    chromatic hardward bloom that I ran over the scene. The algorithm was made 
    up on the spot, so I wouldn't take it too seriously. Having said that, one
    of the problems I have with bloom is that it requires too much work to 
    implement. This one can be dropped right into the tab that runs the buffer
    and that's it. I have some simpler examples that focus on the hardware
    bloom only, so I'll endeavor to post those later.



    Other examples:

    // Fizzer covered a lot of the common polyhedral traversals a 
    // while ago. This one is well written and really nice to look at.
    Octahedral Voxel Tracing - fizzer
    https://www.shadertoy.com/view/4lcfDB


    // Method for finding the nearest octahedron. 
    // Unfortunately, the link is no longer working.
    http://amietia.com/slashmaze.html

*/


// Packing in some spheres. Interesting, but looks a little too
// busy for this example.
#define SPHERES


vec4 gObjD;

// Maximum ray distance.
#define FAR  15.

// Global cell scale. Values of about "1./2." to "1./6" work, 
// but it's designed to work with the currect value.
vec3 GSCALE = vec3(1, 1, 1)/1.;

// Light type: Point: 0, Direct: 1
#define LIGHT_TYPE 0 

//////////////

// Standard 2D rotation formula.
mat2 rot2(in float a){ float c = cos(a), s = sin(a); return mat2(c, s, -s, c); }

/*
// 3D texture lookup. Sometimes faster.
float hash31(vec3 f){

    return texture(iChannel2, f/32.).x;
}
*/

// IQ's "uint" based uvec3 to float hash with Fabrice's modification.
float hash31(vec3 f){


    uvec3 p = floatBitsToUint(f);
    p = 1664525U*((p >> 2U)^(p.yzx>>1U)^p.zxy);
    uint h32 = 1103515245U*(((p.x)^(p.y>>3U))^(p.z>>6U));

    uint n = h32^(h32 >> 16);
    return float(n & uint(0x7fffffffU))/float(0x7fffffff);

}

/*
// Commutative smooth maximum function. Provided by Tomkh, and taken 
// from Alex Evans's (aka Statix) talk: 
// http://media.lolrus.mediamolecule.com/AlexEvans_SIGGRAPH-2015.pdf
// Credited to Dave Smith @media molecule.
float smax(float a, float b, float k){

   float f = max(0., 1. - abs(b - a)/k);
   return max(a, b) + k*.25*f*f;
}
*/

// Tri-Planar blending function: Based on an old Nvidia writeup:
// GPU Gems 3 - Ryan Geiss: http://http.developer.nvidia.com/GPUGems3/gpugems3_ch01.html
vec3 tex3D(sampler2D tex, in vec3 p, in vec3 n){    

    // Abosolute normal with a bit of tightning.
    n = max(n*n - .2, .001); // max(abs(n), 0.001), etc.
    n /= dot(n, vec3(1)); 
    //n /= length(n); 

    // Texure samples. One for each plane.
    vec3 tx = texture(tex, p.zy).xyz;
    vec3 ty = texture(tex, p.xz).xyz;
    vec3 tz = texture(tex, p.xy).xyz;

    // Multiply each texture plane by its normal dominance factor.... or however you wish
    // to describe it. For instance, if the normal faces up or down, the "ty" texture 
    // sample, represnting the XZ plane, will be used, which makes sense.

    // Textures are stored in sRGB (I think), so you have to convert them to linear space 
    // (squaring is a rough approximation) prior to working with them... or something like
    // that. :) Once the final color value is gamma corrected, you should see correct 
    // looking colors.
    return mat3(tx*tx, ty*ty, tz*tz)*n;
}


// The path is a 2D sinusoid that varies over time, depending upon the frequencies, 
// and amplitudes.
vec2 path(in float z){ 

    //return vec2(0);
    float s = sin(z/9.);
    float c = cos(z/13.); 
    return vec2(s*c*8., (s + c)*4.); 
}

// Height map value.
float hm(in vec3 p){ 

    // This is a very basic 3D surface with a camera-path directed tunnel
    // carved out of it. Pretty standard for tunnels.
    vec2 pth = path(p.z);
    float h = (dot(sin(p - cos(p.yzx*2.)), vec3(1./6.)) + .5)*8. - 0.;

    // Carving out the tunnel.
    h = max(h, -(length(p.xy - pth) - 6.));
    return h; // floor(h/GSCALE.y)*GSCALE.y;


}

// Cell color.
vec3 getCol(vec3 id){



    //return vec3(snd);
    //return vec3(.25, .5, 1);
    return (.45 + .5*cos(6.2831*hash31(id + .113)/3. + vec3(0, 1, 2)));
}


// IQ's line distance formula.
float distLine(vec3 p, vec3 a, vec3 b){

    p -= a; b -= a;
    float h = clamp(dot(p, b)/dot(b, b), 0., 1.);
    return length(p - b*h);
}


// Plane function.
float plane(vec3 p, vec3 n, float d){ return dot(p, n) + d; }

// Ray origin, ray direction, point on the line, normal. 
float rayLine(vec3 ro, vec3 rd, vec3 p, vec3 n){

   // This it trimmed down, and can be trimmed down more. Note that 
   // "1./dot(rd, n)" can be precalculated outside the loop.
   //return dot(p - ro, n)/dot(rd, n);
   float dn = dot(rd, n);
   return dn>0.? dot(p - ro, n)/dn : 1e8;   

} 

vec3 lp, ld;

// Global cell boundary distance variables.
vec3 gDir; // Cell traversing direction.
vec3 gRd; // Ray direction.
float gCD; // Cell boundary distance.
// Box dimension and local XY coordinates.
vec3 gSc; 
vec3 gP;
vec4 gID;

// Saving the step variable.
vec3 gN;

// Octahedral cell coordinates and ID. Thankfully, Fizzer determined a very
// simple, and clever, method to determine these years ago.
vec3 getCell(inout vec3 p, inout vec3 sc){    

    // General coordinate copy.
    vec3 oP = p;

    // Snap to the nearest cube.
    vec3 ip = floor(p/sc) + .5;

    p -= ip*sc; // Local cube coordinates. Equivalent to: fract(p) - .5.

    // Stepping trick used to identify faces in a cube. The center of the cube face also
    // happens to be the center of the nearest octahedron. The cube mapping technique has 
    // been around for a while, but its usage as an octahedron partitioning scheme came
    // from one of Fizzer's articles, here:
    //
  	// Implicit Maze-Like Patterns - Fizzer
    // http://amietia.com/slashmaze.html
    //
    vec3 n = abs(p); 
    n = step(n.yzx, n)*step(n.zxy, n)*sign(p); // Used for cube mapping also.

    gN = n;

    // Update the position-based ID and use it to calculate the local octagon 
    // cell coordinates.
    ip += n*.5;
    p = oP - ip*sc;

    gP = p;

    return ip;

}

// Signed distance to a pyramid of base "scl" and height "h".
// IQ's (double) pyramid function, modified by myself to take in 
// variable base values. Trust the original below, but not this one. :)
//
// Octahedron - distance -- iq
// https://www.shadertoy.com/view/wsSGDG
//
// IQ goes to a lot of trouble to write these, and they always 
// work as advertised. :)
float sdOctahedron(vec3 p, float h, float scl){

/*     
    // Hacky bound version: It seems to work, and also appears to run 
    // faster. However, I don't feel it looks as nice... Plus, I don't
    // trust anything I write myself. :D
    p = abs(p);
    p.xz -= max(scl/2. - p.y, 0.);
    return max(max(p.x, p.z), p.y - h);
*/    


    scl /= 2.;
    float m2 = (h*h + scl*scl);

    // Symmetry.
    p = abs(p); // p = abs(p), for a double pyramid.
    p.xz = (p.z>p.x) ? p.zx : p.xz;
    p.xz -= scl; 

    // Project into face plane (2D).
    vec3 q = vec3( p.z, h*p.y - p.x*scl, h*p.x + p.y*scl);

    float s = max(-q.x, 0.);
    float t = clamp((q.y - q.x*scl)/(m2 + scl*scl), 0., 1.);

    float a = m2*(q.x + s)*(q.x + s) + q.y*q.y;
	float b = m2*(q.x + t*scl)*(q.x + t*scl) + (q.y - m2*t)*(q.y - m2*t);

    float d2 = max(-q.y, q.x*m2 + q.y*scl) < 0. ? 0. : min(a, b);

    // recover 3D and scale, and add sign
    return sqrt((d2 + q.z*q.z)/m2)*sign(max(q.z, -p.y));
}

int faceID;


float map(vec3 q3) {


    // Floor. Redundant here, but I'm keeping it around for later.
    vec2 pth = path(q3.z);
    float fl = 1e5;


    vec3 sc = GSCALE; // Scale.



    // Local coordinates and cell ID.
    vec3 p = q3;
    // Otaghedral cell position and coordinates. 
    vec3 p3 = getCell(p, sc); 
    // Position based ID.
    vec3 id = p3;

     //  CELL INTERSECTION.

    // Initial octahedral face directions. The following are the top
    // four face directions for a Y-axis oriented one. The negative
    // vectors will give you the lower four.
    const vec3[4] nn = vec3[4](vec3(-1, 1, 0), vec3(1, 1, 0),
                               vec3(0, 1, -1), vec3(0, 1, 1));


    // Maximize the ray distance.
    float t = 1e8;

    // You could calculate the field distance to the object
    // inside the following loop, but we'll use other methods.
    float obj = -1e5; 


    float smF = .0;//.08;

    vec3 svP = p;

    // Rotating the local coordinates and directional ray intersection 
    // vector according to which octahedron (central cube face) we're in.
    //
    // Unfortunately, packed octahedrons are oriented differently,
    // depending on relative cube face position. To the left and right,
    // it's a 90 degree XY rotation, front and back require 90 degree
    // YZ rotation, and up and down remain the same. However, as you can
    // see, the reorientation code is pretty simple.
    vec3 svRd = gRd;
    if(abs(gN.x)>.5){ p = p.yxz; svRd = svRd.yxz; } // Left and right.
    if(abs(gN.z)>.5){ p = p.xzy; svRd = svRd.xzy; } // Fron and back.

    // Ray to cell wall distance. We're using a symmetry trick to 
    // halve the number of wall intersections necessary.
    for(int i = 0; i<4; i++){

        // Cell wall direction.
        vec3 fR = nn[i];
        fR *= sc/4.;

        // Using a traversal trick for symmetric objects. In particular
        // reversing the point and normal direction if the ray is heading 
        // in the opposite direction. This cuts down calculations from 8
        // to four, in this case, which is pretty helpful inside a 
        // raymarching loop.
        fR = dot(svRd, fR)<0.? -fR : fR;

        // Distance to the cell wall of the plane in the direction of
        // the ray.
        //
        // Ray origin, ray direction, point on the face, normal. 
        // The point on the face is half the normal length.
        float ti = rayLine(p, svRd, fR, normalize(fR));
        // Record the minimum distance.
        t = min(ti, t);

    }

   /*

    // The raymarching object using planes.
    for(int i = 0; i<8; i++){

        // Cell wall direction.
        vec3 fR = nn[i%4];
        fR *= sc/4.;
        if(i>3) fR *= -1.;

        // Object field distance... Not to be confused with the
        // directional ray to cell wall intersection above.
        //obj = smax(obj, dot((p) - fR, normalize(fR)), smF);

        float pln = dot((p) - fR, normalize(fR));
        if(pln>obj){

           obj = pln;//smax(obj, pln, smF);
           faceID = i;
        }

        //obj = smax(obj, pln, smF);
    } */




    faceID = 0;
    if(p.x + p.z>0.) faceID += 4; // XZ diagonal.
    if(p.y>0.) faceID += 2; // Top or bottom pyramid.
    if(p.x - p.z>0.) faceID += 1; // Other XZ diagonal.



    // Distance to the next cell in the direction of the ray.
    gCD = max(t, 0.) + .0001;

    // RAYMARCHING.

    float d = 1e5;

    // A thin frame that encased the object above.
    float dFrame = 1e5;


    // The 3D field value.
    float h = hm(id*sc);


    // Render blocks for anything under the field value threshold.
    if(h<4.){

        // Octahedral pyramid object.
        obj = sdOctahedron(p, sc.x/2., sc.x);

        d = obj + .0001;


        float svD = d;

        // Octahedron edges.
        vec3 ap = abs(p);
        float e1 = (dot(ap, vec3(0, 1, 0))); // Square sides.
        float e2 = (dot(ap, vec3(1, 0, -1)/sqrt(2.))); // Pyramid XZ.
        e2 = min(e2, (dot(ap, vec3(1, 0, 1)/sqrt(2.)))); // Other XZ.

        // Combined edge frame object.
        dFrame = min(abs(e1), abs(e2));
        // Edge width.
        float eW = .135*sc.x;

        // Octahedral random number.
        float rnd = hash31(id + .01);
        // Octahedral side random number.
        float rnd2 = hash31(id + float(faceID)/8. + .03);

        // Holes in some sides.
        if(rnd2<.35){
          float hole = max(dFrame, -(dFrame - eW));
          d = max(d, (dFrame - eW));
          d = d + hole*.125;
        }
        else d = d + .01 - dFrame*.125; // Raised sides.

        // Hole edges.
        if(rnd2<.35) dFrame = min(dFrame, abs(dFrame - eW));
        dFrame = max(dFrame - .005, obj); // Frame.
        // dFrame = 1e5;

        #ifdef SPHERES
        // Packing in some spheres.
        if(rnd<.15){
           d = length(p) - sc.x/2./sqrt(2.) + .0015;
           dFrame = 1e5;
           faceID = 0;
        }
        #endif



    }


    // Saving the object dimensions, local coordinates and ID.
    gSc = sc; 
    gP = p;
    gID = vec4(1e5, id);

    // Saving the individual distance fields for sorting later.
    // Sorting things inside the loop can sometimes be more costly.
    // Not always, but with lots of objects, it usually is.
    gObjD = vec4(fl, d, dFrame, 1e5);

    // Scene distance.
    return min(fl, min(d, dFrame));
}



float rayMarch(vec3 ro, vec3 rd) {

    float d, t = 0.;//hash31(ro + rd)*.25; // Glow jitter.
    vec2 dt = vec2(1e8, 0); // IQ's edge desparkle trick.

    // Set the global ray direction varibles -- Used to calculate
    // the cell boundary distance inside the "map" function.
    gDir = step(0., rd) - .5;
    gRd = rd;

    const int iter = 160;
    int i = 0;

    for (i = 0; i<iter; i++) {

        d = map(ro + rd*t);

        // IQ's clever edge desparkle trick. :)
        if (d<dt.x) { dt = vec2(d, t); } 

        if (d<.001 || t>FAR){
            break;
        }

        // Advance the ray no more than the 
        // cell-wall delimiting distance.
        t += min(d*.9, gCD);
    }

    if(i == iter - 1) { t = dt.y; }

    // Don't go further than the far plane.
    return min(t, FAR);
}

float softShadow(in vec3 p, in vec3 ld, in float lDist, in float k) {

    float res = 1.;
    float t = 0.;

    // Set the global ray direction varibles -- Used to calculate
    // the cell boundary distance inside the "map" function.
    gDir = step(0., ld) - .5;
    gRd = ld; 

    for (int i=0; i<64; i++){

        float d = map(p + ld*t);
        res = min(res, k*d/t);
        if (d<0. || t>lDist) break;

        t += clamp(min(d*.9, gCD), .01, .25);
    }
    return clamp(res, 0., 1.);
}

// Normal function. It's not as fast as the tetrahedral calculation, but more symmetrical.
vec3 normal(in vec3 p) {

    //return normalize(vec3(map(p + e.xyy) - map(p - e.xyy), map
    //                      map(p + e.yxy) - map(p - e.yxy),	
    //                      map(p + e.yyx) - map(p - e.yyx)));

    // This mess is an attempt to speed up compiler time by contriving a break... It's 
    // based on a suggestion by IQ. I think it works, but I really couldn't say for sure.
    float sgn = 1.;
    vec3 e = vec3(.002, 0, 0), mp = e.zzz; // Spalmer's clever zeroing.
    for(int i = min(iFrame, 0); i<6; i++){
		mp.x += map(p + sgn*e)*sgn;
        sgn = -sgn;
        if((i&1)==1){ mp = mp.yzx; e = e.zxy; }
    }

    return normalize(mp);
}


// I keep a collection of occlusion routines... OK, that sounded really nerdy. :)
// Anyway, I like this one. I'm assuming it's based on IQ's original.
float calcAO(in vec3 p, in vec3 n){

	float sca = 2., occ = 0.;
    for( int i = 0; i<5; i++ ){

        float hr = float(i + 1)*.2/5.;        
        float d = map(p + n*hr);
        occ += (hr - d)*sca;
        sca *= .7;

        // Deliberately redundant line that may or may not stop the 
        // compiler from unrolling.
        //if(sca>1e5) break;
    }

    return clamp(1. - occ, 0., 1.);
}

// Light distance.
float lDist;


vec4 render(inout vec3 ro, inout vec3 rd, vec2 u){

    // Surface distance.
    float t = rayMarch(ro, rd);


    // Saving the global scale, local cell coorinates and cell ID.
    vec3 svSc = gSc;
    vec3 svP = gP;
    vec4 svGID = gID;

    //vec3 svGN = gN;


    // Object ID: The block, the block frame and the floor.
    int objID = gObjD.x<gObjD.y && gObjD.x<gObjD.z? 0 : gObjD.y<gObjD.z? 1 : 2;

    // Face ID.
    float svFID = float(faceID);


    // Initializing.
    vec3 fog = vec3(0);
    vec3 col = fog;

    // Position.
    vec3 p = ro + rd*t;
    // yzw

    if (t < FAR){

        // Normal.
        vec3 n = normal(p);

        // Light: Point or directional. The directional light
        // doesn't really belong in this particular dark cavernous
        // setting, but it's there anyway.
        #if LIGHT_TYPE == 0
        ld = lp - p;
        lDist = length(ld);
        ld /= lDist;
        #endif


        // Shadow and ambient occlusion.
        float shd = softShadow(p + n*.0015, ld, lDist, 8.);
        float ao = calcAO(p, n);


        // Block ID and corresponding height.
        vec3 id = svGID.yzw;

        //////////////

        // Give the faces a unique ID. We'll use it to create the
        // blinking triangle face effect.
        if(svP.x + svP.z>0.) svFID += 4.; // XZ diagonal.
        if(svP.y>0.) svFID += 2.; // Top or bottom pyramid.
        if(svP.x - svP.z>0.) svFID += 1.; // Other XZ diagonal.

        // Spheres have one face, so give them all the same face ID.
        if(hash31(id + .01)<.15) svFID = 0.;

       // Polyhedral color. 
        vec3 oCol = getCol(id + svFID/8.);

        // Blink color.
        vec3 blCol = oCol;//step(.25, hash31(id + .3))
        blCol = mix(blCol*sqrt(blCol)*12., blCol.yzx*10., smoothstep(.4, .6, u.y*.5 + .5));

        // Darkening about 50 percent of the polyhedral blocks.
        //if(hash31(id + .22)<.5 && objID!=0){

           vec3 fCol = mix(oCol*sqrt(oCol)*1.2, oCol.yzx, smoothstep(.4, .6, u.y*.5 + .5));
           oCol = mix(fCol*.5, vec3(.5)*dot(oCol, vec3(.299, .587, .114)), .7);

        //} 

        // Applying the blinking color to random sides.
        float blR = texture(iChannel2, vec2(mod(abs(hash31(id+ svFID/8.)),1.),0.)).r; 
        blR*=blR; //hash31(id + svFID/8. + .2);

        if(objID!=0){
            oCol = mix(oCol*0.05, blCol, 
                      smoothstep(.487, .497, abs(sin(blR*6.2831853)*.5)));

        }


        /*
        // Debug, to show the 3 different octahedral orientations.
        if(abs(svGQ.x)>.5) oCol = vec3(2, .4, .6);
        if(abs(svGQ.y)>.5) oCol = vec3(.25, 1.5, 2);
        if(abs(svGQ.z)>.5) oCol = vec3(1.8, 1, .2);
        */


        // Darkening the raymarched edge strip object.
        if(objID==2) oCol *= .05;


        // Using different colors.
        //oCol = oCol.zyx;


        // Adding the metallic texture. It's literally the only
        // fined grained texture that Shadertoy has. More would
        // be nice. :)
        vec3 tx = tex3D(iChannel0, p/2., n);
        tx = smoothstep(0., .5, tx);
        oCol *= tx;

        // Diffuse value.
        float dif = max(dot(ld, n), 0.);
        dif = pow(dif, 1.8 + tx.x); // Diffusivity based on texture.

        // Specular value.
        float spe = pow(max(dot(reflect(ld, n), rd), 0.), 32.);

        float spR = pow(max(dot(normalize(ld - rd), n), 0.), 8.);

        vec3 rf = reflect(rd, n); // Surface reflection.
        vec3 rTx = texture(iChannel1, rf.xzy*vec3(1, 1, 1)).xyz; rTx *= rTx;
        oCol = oCol + oCol*spR*rTx.yzx*8.;


        // Cheap ambient lighting from Blackle's example, here:
        // Quick Lighting Tech - blackle
        // https://www.shadertoy.com/view/ttGfz1
        //
        // Studio.
        float am = pow(length(sin((n)*3.14159/4.)*.5 + .5)/sqrt(3.), 2.)*1.5; 
        // Outdoor.
        //float am = length(sin(sn*2.)*.5 + .5)/sqrt(3.)*smoothstep(-1., 1., -sn.z); 


        // Lit color.
        col = oCol*(am + vec3(1, 1, .5)*dif*shd + vec3(1, .6, .4)*spe*shd*4.);


        // Light attenuation.
        float rt = t/FAR;
        col *= 1./(1. + rt*.2); 


    }


    // Apply the fog.
    col = mix(col, fog, smoothstep(.3, .99, t/FAR));


    // Returning the final color for this pass... There's only one
    // pass here, but a render function is useful when you want to
    // bounce light around.
    return vec4(col, t);

}




void mainImage(out vec4 fragColor, in vec2 fragCoord ) {

    // Coordinates.
    vec2 u = (fragCoord - iResolution.xy*.5)/iResolution.y;

    /*
    // Cinematic strip.
    if(abs(u.y)>.42){
       fragColor = vec4(0);
       return;
    }
    */

    // Saving the screen coordinates.
    vec2 svU = u;

    // Screen bulge.
    u *= 1. + dot(u, u);

    // Look vector and camera origin.
    vec3 lk = vec3(0, -.6, iTime*2.);
    vec3 ro = lk + vec3(0, 0, -2.5);

    // Light.
    #if LIGHT_TYPE == 0
    lp = ro + vec3(0, 0, 4);
    lp.xy += path(lp.z);
    #else
    ld = normalize(vec3(0, 4, 4));
    lDist = FAR;
    #endif

    // Moving the camera along the path.
    lk.xy += path(lk.z);
	ro.xy += path(ro.z);

    // Setting up a camera using the usual process. The variable names
    // here suggest that this lot came from one of IQ's examples.
    vec3 ww = normalize(lk - ro);
    vec3 uu = normalize(cross(vec3(0, 1, 0), ww ));
    vec3 vv = cross(ww, uu);
    const float FOV = 3.14159/3.; // Field of view.
    vec3 rd = normalize(u.x*uu + u.y*vv + ww/FOV); // Unit direction vector.


    // Swiveling the camera from left to right when turning corners.
    rd.xy = rot2(path(lk.z).x/24.)*rd.xy; 

    // Mouse movement.
    if(iMouse.z>1.){
        vec2 ms = -(iMouse.xy - iResolution.xy*.5)/iResolution.y;
        rd.yz *= rot2(ms.y*3.1459);  
        rd.xz *= rot2(ms.x*3.1459);  
    } 


    // Angling the camera toward the tunnel wall for a more warped perspective.
    rd.xz *= rot2(-3.1459265/3.);
    rd.xy *= rot2(3.14159/4.);

    // Ray distortion. I'm already performing screen distortion (at
    // the UV level), so we don't really need it.
    //rd = normalize(vec3(rd.xy, rd.z*(1. + dot(rd.xy, rd.xy)*.5)));


    // Render.
    vec4 c4 = render(ro, rd, svU);

    // Store the color in the buffer.
    fragColor = vec4(max(c4.xyz, 0.), 1.);


}
